import java.io.*; import java.util.*; import java.math.BigInteger;
import org.apache.hadoop.conf.*; import org.apache.hadoop.fs.*; import org.apache.hadoop.io.*; import org.apache.hadoop.mapreduce.*; import org.apache.hadoop.mapreduce.lib.input.*; import org.apache.hadoop.mapreduce.lib.output.*;
public class UnswMapReduce {
 static String[] csv(String s){ List<String> a=new ArrayList<>(); StringBuilder b=new StringBuilder(); boolean q=false; for(int i=0;i<s.length();i++){char c=s.charAt(i); if(c=='"'){if(q&&i+1<s.length()&&s.charAt(i+1)=='"'){b.append(c);i++;}else q=!q;}else if(c==','&&!q){a.add(b.toString());b.setLength(0);}else b.append(c);}a.add(b.toString()); return a.toArray(new String[0]); }
 static String cat(String[] x){String l=x[48].trim(), c=x[47].trim(); if(l.equals("0")&&(c.isEmpty()||c.equalsIgnoreCase("none")||c.equalsIgnoreCase("null")))return "Normal"; if(c.equalsIgnoreCase("backdoors"))return "Backdoor"; return c;}
 static BigInteger n(String s){return new BigInteger(s.trim());}
 public static class CatMap extends Mapper<LongWritable,Text,Text,LongWritable>{public void map(LongWritable k,Text v,Context c)throws IOException,InterruptedException{String[]x=csv(v.toString());if(x.length==49)c.write(new Text(cat(x)),new LongWritable(1));}}
 public static class ProtoMap extends Mapper<LongWritable,Text,Text,Text>{public void map(LongWritable k,Text v,Context c)throws IOException,InterruptedException{String[]x=csv(v.toString());if(x.length==49)c.write(new Text(x[4].trim()),new Text("1,"+n(x[7]).add(n(x[8]))+","+(x[48].trim().equals("1")?1:0)));}}
 public static class SrcMap extends Mapper<LongWritable,Text,Text,Text>{public void map(LongWritable k,Text v,Context c)throws IOException,InterruptedException{String[]x=csv(v.toString());if(x.length==49)c.write(new Text(x[0].trim()),new Text("1,"+n(x[7]).add(n(x[8]))+","+(x[48].trim().equals("1")?1:0)));}}
 static final class Totals {final BigInteger flows,bytes,attacks; Totals(BigInteger f,BigInteger b,BigInteger a){flows=f;bytes=b;attacks=a;} Totals add(Totals o){return new Totals(flows.add(o.flows),bytes.add(o.bytes),attacks.add(o.attacks));}}
 static Totals totals(String value){String[] p=value.split(",",-1);if(p.length!=3)throw new IllegalArgumentException("Expected flow_count,byte_total,attack_count: "+value);return new Totals(n(p[0]),n(p[1]),n(p[2]));}
 static String intermediate(Totals t){return t.flows+","+t.bytes+","+t.attacks;}
 static Totals sum(Iterable<Text> values){Totals result=new Totals(BigInteger.ZERO,BigInteger.ZERO,BigInteger.ZERO);for(Text value:values)result=result.add(totals(value.toString()));return result;}
 public static class TotalsCombiner extends Reducer<Text,Text,Text,Text>{public void reduce(Text k,Iterable<Text>vs,Context c)throws IOException,InterruptedException{c.write(k,new Text(intermediate(sum(vs))));}}
 public static class TotalsReducer extends Reducer<Text,Text,Text,Text>{public void reduce(Text k,Iterable<Text>vs,Context c)throws IOException,InterruptedException{Totals t=sum(vs);c.write(k,new Text(t.flows+"\t"+t.bytes+"\t"+t.attacks));}}
 public static class Count extends Reducer<Text,LongWritable,Text,LongWritable>{public void reduce(Text k,Iterable<LongWritable>v,Context c)throws IOException,InterruptedException{long n=0;for(LongWritable x:v)n+=x.get();c.write(k,new LongWritable(n));}}
 public static void main(String[]z)throws Exception{if(z.length!=3)throw new IllegalArgumentException("mode input output"); Configuration c=new Configuration(); Job j=Job.getInstance(c,"unsw-"+z[0]);j.setJarByClass(UnswMapReduce.class); if(z[0].equals("category")){j.setMapperClass(CatMap.class);j.setCombinerClass(Count.class);j.setReducerClass(Count.class);j.setMapOutputValueClass(LongWritable.class);j.setOutputValueClass(LongWritable.class);}else{j.setMapperClass(z[0].equals("protocol")?ProtoMap.class:SrcMap.class);j.setCombinerClass(TotalsCombiner.class);j.setReducerClass(TotalsReducer.class);j.setMapOutputValueClass(Text.class);j.setOutputValueClass(Text.class);}j.setOutputKeyClass(Text.class);FileInputFormat.addInputPath(j,new Path(z[1]));FileOutputFormat.setOutputPath(j,new Path(z[2]));System.exit(j.waitForCompletion(true)?0:1);}
}
